export function toSql(schema: Schema) {
  return schema.tables
    .map(createTable)
    .join('\n\n');
}

SELECT project_id, COUNT(*) AS items
FROM elements
GROUP BY project_id;

CREATE TABLE share_links (
  token VARCHAR(32) PRIMARY KEY,
  project_id BIGINT NOT NULL
);

export function undo() {
  const step = history.pop();
  step?.revert();
  redoStack.push(step);
}

export function pairs(a: Slide, b: Slide) {
  return a.items.filter((i) => b.byTag(i.morphId));
}

ALTER TABLE elements
  ADD COLUMN locked BOOLEAN
  DEFAULT false;
